<script setup>
import {ref,computed,onMounted,onBeforeUnmount,nextTick} from 'vue'
import {Phone,ShieldCheck,RefreshCw,CheckCircle2,ArrowRight,Smartphone} from 'lucide-vue-next'
import WhatsAppPublicProfile from './WhatsAppPublicProfile.vue'
const catalog=ref(null),number=ref(''),state=ref(null),name=ref(''),code=ref(''),confirmed=ref(false),busy=ref(false),error=ref(''),notice=ref(''),now=ref(Date.now())
const policy=ref({enabled:false,waba_id:''}),needsConsult=ref(false)
let timer
const chosen=computed(()=>catalog.value?.numbers.find(n=>n.number===number.value))
const remaining=computed(()=>state.value?.retry_after?Math.max(0,Math.ceil((Date.parse(state.value.retry_after)-now.value)/1000)):0)
const waitLabel=computed(()=>remaining.value>3600?Math.floor(remaining.value/3600)+' h '+Math.floor((remaining.value%3600)/60)+' min':remaining.value>60?Math.ceil(remaining.value/60)+' min':remaining.value+' s')
const profile=computed(()=>state.value?.sender_id?{id:state.value.sender_id,number:number.value,status:state.value.status,provider:'twilio'}:null)
const canRequest=computed(()=>state.value?.can_request&&!remaining.value&&!needsConsult.value)
async function api(action='',body){
 const aborter=new AbortController(),timeout=setTimeout(()=>aborter.abort(),45000)
 try{const r=await fetch('/api/voice/whatsapp/verification'+(action?'/'+action:''),{method:body?'POST':'GET',signal:aborter.signal,headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]')?.content||''},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json().catch(()=>({message:'Não foi possível confirmar a resposta. Atualize o andamento.'}));if(!r.ok)throw Error(d.errors?Object.values(d.errors).flat().join(' · '):d.message||'Não foi possível concluir.');now.value=Date.now();return d}
 catch(e){if(e.name==='AbortError')throw Error('A consulta demorou mais que o esperado. Consulte o andamento antes de repetir uma solicitação.');throw e}finally{clearTimeout(timeout)}
}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function local(){state.value=await api('status',{number:number.value});if(!name.value)name.value=state.value.display_name||''}
async function choose(){state.value=null;name.value='';code.value='';confirmed.value=false;needsConsult.value=false;if(number.value)await run(local)}
async function load(){catalog.value=await api();if(catalog.value.policy)policy.value={...catalog.value.policy};if(!catalog.value.numbers.some(n=>n.number===number.value))number.value=catalog.value.numbers[0]?.number||'';if(number.value)await local();else state.value=null}
async function inspect(){await run(async()=>{state.value=await api(state.value?.setup_ready?'inspect':'status',{number:number.value});needsConsult.value=false;notice.value='Andamento atualizado. Nenhum código novo foi solicitado.'})}
async function request(){await run(async()=>{needsConsult.value=true;state.value=await api('request',{number:number.value,name:name.value.trim(),confirmed:confirmed.value});confirmed.value=false;needsConsult.value=false;if(state.value.status==='PENDING_VERIFICATION'){await nextTick();document.getElementById('wa-verification-code')?.focus()}})}
async function verify(){const value=code.value;code.value='';await run(async()=>{needsConsult.value=true;state.value=await api('verify',{number:number.value,code:value});needsConsult.value=false})}
async function save(){await run(async()=>{const r=await api('settings',{enabled:policy.value.enabled,waba_id:policy.value.waba_id||null});policy.value=r.policy;if(number.value)await local();notice.value='Configuração salva. Nenhuma chamada foi solicitada.'})}
onMounted(()=>{run(load);timer=setInterval(()=>{now.value=Date.now()},1000)})
onBeforeUnmount(()=>{clearInterval(timer);code.value=''})
</script>
<template>
 <section class="wv" :aria-busy="busy">
  <header class="wv-heading"><div class="wv-icon"><ShieldCheck :size="27"/></div><div><span class="eyebrow">WHATSAPP OFICIAL</span><h1>Seu número. Sua empresa.</h1><p>Receba uma ligação e confirme o código para conectar seu número.</p></div><button class="secondary" :disabled="busy" @click="run(load)"><RefreshCw :size="16"/>Atualizar</button></header>
  <p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="wv-notice" role="status">{{notice}}</p>
  <p v-if="!catalog" class="wv-notice">{{error?'Use Atualizar para carregar seus números.':'Carregando números da sua empresa…'}}</p>
  <template v-else>
   <ol class="wv-steps" aria-label="Etapas da conexão"><li :class="{active:number}"><span>1</span>Escolher número</li><li :class="{active:state?.status==='PENDING_VERIFICATION'}"><span>2</span>Receber ligação</li><li :class="{active:state?.state==='online'}"><span>3</span>Confirmar código</li></ol>
   <div v-if="!catalog.numbers.length" class="wv-card wv-empty"><Smartphone :size="32"/><h2>Nenhum número disponível</h2><p>Solicite um número em Meus números. A administração também pode vincular uma linha já contratada à sua empresa.</p></div>
   <div v-else class="wv-grid">
    <article class="wv-card"><span class="eyebrow">01 · SELECIONE A LINHA</span><h2>Qual número deseja conectar?</h2><label>Número da sua empresa<select v-model="number" :disabled="busy" @change="choose"><option v-for="n in catalog.numbers" :key="n.number" :value="n.number" :disabled="n.qr_conflict">{{n.number}} · {{n.operator}}{{n.status==='ONLINE'?' · Conectado':''}}{{n.qr_conflict?' · Revisar migração':''}}</option></select></label><p class="wv-help">A lista mostra somente números vinculados à sua empresa. A ligação será feita para o número selecionado.</p>
     <template v-if="state">
      <div class="wv-status" :class="{success:state.state==='online'}" role="status"><CheckCircle2 v-if="state.state==='online'" :size="22"/><strong>{{state.state==='online'?'WhatsApp conectado':!state.setup_ready?'Aguardando liberação':state.status==='PENDING_VERIFICATION'?'Aguardando seu código':'Verificação do número'}}</strong><p>{{state.message}}</p><p v-if="remaining"><b>Pausa da DiscAI: {{waitLabel}}</b><br>Após a pausa, consulte o andamento. Nenhuma tentativa será feita automaticamente.</p></div>
      <form v-if="state.state!=='online'&&!['PENDING_VERIFICATION','VERIFYING','CREATING','TWILIO_REVIEW','ONLINE:UPDATING'].includes(state.status)" @submit.prevent="request">
       <label>Nome da empresa no WhatsApp<input v-model="name" maxlength="100" minlength="2" required placeholder="Ex.: Bossa Nova SIR" :disabled="busy||!state.setup_ready"></label><p class="wv-help">O nome será enviado à análise da Meta.</p>
       <label class="wv-check"><input type="checkbox" v-model="confirmed" :disabled="busy||!state.setup_ready">Tenho autorização para conectar este número e há alguém pronto para atender a ligação.</label>
       <button class="primary wv-full" :disabled="busy||!canRequest||!confirmed||name.trim().length<2"><Phone :size="17"/>{{busy?'Aguarde…':'Solicitar ligação com código'}}</button>
      </form>
      <form v-if="state.status==='PENDING_VERIFICATION'" @submit.prevent="verify" class="wv-code"><label>Código recebido na ligação<input id="wa-verification-code" v-model="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" placeholder="000000" required :disabled="busy||!state.can_verify||needsConsult"></label><p class="wv-help">Digite os seis dígitos ouvidos. O código não fica salvo na DiscAI.</p><button class="primary wv-full" :disabled="busy||!state.can_verify||!!remaining||needsConsult||!/^\d{6}$/.test(code)">Confirmar código <ArrowRight :size="16"/></button></form>
      <button class="secondary wv-full wv-refresh" :disabled="busy" @click="inspect"><RefreshCw :size="16"/>Consultar andamento</button>
     </template>
    </article>
    <aside class="wv-card"><span class="eyebrow">02 · PREPARE O RECEBIMENTO</span><h2>Pronto para atender?</h2><div class="wv-reception" :class="{ready:state?.reception.ready}"><span class="wv-dot"></span><div><strong>{{state?.reception.ready?'Atendimento disponível':'Confira sua fila de entrada'}}</strong><p>{{state?.reception.message||'Selecione um número para conferir o recebimento.'}}</p></div></div>
     <ol class="wv-instructions"><li>Deixe um atendente <b>disponível</b> na fila de entrada deste número, com áudio e navegador conectados.</li><li>Solicite a ligação, atenda e anote os seis dígitos informados pela Meta.</li><li>Volte a esta tela e confirme o código. A ativação será exibida após a confirmação do provedor.</li></ol>
     <a class="secondary wv-full" href="#/operation" target="_blank" rel="noopener">Abrir Minha operação em outra aba ↗</a><button class="secondary wv-full wv-refresh" :disabled="busy||!number" @click="run(local)">Atualizar disponibilidade</button>
     <details class="wv-faq"><summary>A ligação não chegou?</summary><p>Consulte o andamento e confira o receptivo. Não solicite códigos repetidamente. Se o provedor limitar as tentativas ou for necessário reenviar, a administração precisará revisar o cadastro.</p><p>Ter uma linha de voz não ativa automaticamente o WhatsApp. A conta empresarial e o número precisam ser autorizados pelo provedor.</p></details>
    </aside>
   </div>
   <div v-if="profile" class="wv-card wv-profile"><WhatsAppPublicProfile :key="profile.id" :sender="profile"/></div>
   <details v-if="catalog.platform_admin" class="wv-card wv-admin"><summary>Administração DiscAI · liberação desta empresa</summary><p>Libere somente após a autorização empresarial e a primeira ativação no provedor. O vínculo é conferido com a conexão WhatsApp deste ambiente; o cliente não vê estes campos.</p><form @submit.prevent="save"><label>Conta empresarial WhatsApp autorizada (WABA ID)<input v-model="policy.waba_id" inputmode="numeric" pattern="[0-9]{5,40}" :required="policy.enabled" :disabled="busy" placeholder="Identificador aprovado no provedor"></label><label class="wv-check"><input type="checkbox" v-model="policy.enabled" :disabled="busy">Empresa autorizada: permitir verificação das linhas atribuídas</label><button class="secondary" :disabled="busy">Salvar liberação</button></form></details>
   <a class="wv-link" href="#/cadences/channels/whatsapp">Gerenciar perfis, templates e mensagens <ArrowRight :size="16"/></a>
  </template>
 </section>
</template>
<style scoped>
.wv{max-width:1180px;margin:auto;color:#2e473b;line-height:1.65}.wv-heading{display:flex;gap:18px;align-items:center;margin:0 0 28px}.wv-heading>div:nth-child(2){flex:1}.wv-heading h1{font-size:30px;letter-spacing:-.8px;margin:4px 0}.wv-heading p{color:#718072;margin:0;font-size:14px}.wv-icon{display:grid;place-items:center;width:60px;height:60px;border-radius:19px;background:#f4ebd6;color:#a47b28;flex-shrink:0}.wv-steps{display:flex;gap:28px;padding:18px 0;margin-bottom:28px;border-block:1px solid #dee5d8;list-style:none;flex-wrap:wrap;font-size:13px;color:#7b8575}.wv-steps li{display:flex;gap:9px;align-items:center}.wv-steps span{display:grid;place-items:center;width:27px;height:27px;background:#edf0e6;border-radius:50%;font-weight:600}.wv-steps .active{color:#70521a}.wv-steps .active span{background:#f0e2be}.wv-grid{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,1fr);gap:24px;align-items:start}.wv-card{background:#fff;border:1px solid #dce5d5;border-radius:21px;padding:28px;box-shadow:0 8px 26px #233b2907;min-width:0}.wv h2{font-size:21px;letter-spacing:-.4px;margin:8px 0 24px}.wv label:not(.wv-check){display:flex;flex-direction:column;gap:8px;font-size:13px;font-weight:600;margin:20px 0 8px}.wv input:not([type=checkbox]),.wv select{width:100%;min-width:0;border:1px solid #d4dfcc;border-radius:11px;padding:13px 14px;font:inherit;color:#304b3d;background:white}.wv button,.wv a.secondary{display:inline-flex;justify-content:center;align-items:center;gap:9px;white-space:normal}.wv button:disabled{opacity:.5;cursor:not-allowed}.wv :focus-visible{outline:3px solid #c69c4055;outline-offset:3px}.wv-full{width:100%}.wv label.wv-check{display:flex;flex-direction:row;align-items:flex-start;gap:10px;font-size:12px;line-height:1.7;margin:22px 0}.wv .wv-check input{width:16px;height:16px;flex:0 0 16px;margin-top:4px;accent-color:#bd9138}.wv-help{font-size:12px;color:#74816c;margin:8px 0 18px}.wv-status{background:#fcf7e9;border:1px solid #e9d8af;border-radius:13px;padding:18px;margin:22px 0;color:#7e652d}.wv-status p{font-size:13px;margin:7px 0 0}.wv-status.success{background:#eff7ec;border-color:#d3e6cb;color:#3b6b46}.wv-status svg{vertical-align:middle;margin-right:8px}.wv-refresh{margin-top:12px}.wv-code input{font-size:25px!important;letter-spacing:.3em}.wv-reception{display:flex;align-items:flex-start;gap:12px;border-radius:13px;background:#f5f5ef;border:1px solid #e2e6d9;padding:16px;font-size:13px}.wv-reception p{color:#76806d;margin:5px 0 0;font-size:12px}.wv-reception.ready{background:#eff6ec;border-color:#d1e2c8}.wv-dot{margin-top:8px;width:8px;height:8px;border-radius:50%;background:#b2965c;flex-shrink:0}.ready .wv-dot{background:#5c9061}.wv-instructions{padding-left:21px;margin:24px 0;color:#637461;font-size:13px}.wv-instructions li{padding-left:6px;margin:16px 0}.wv-faq{margin-top:25px;padding-top:20px;border-top:1px solid #e2e8dd;font-size:13px}.wv-faq p,.wv-admin p{color:#72806e;font-size:12px}.wv summary{cursor:pointer;font-weight:600}.wv-profile,.wv-admin{margin-top:24px}.wv-admin form{max-width:580px}.wv-notice{padding:16px;border-radius:12px;border:1px solid #d7e6cf;background:#f0f6eb;font-size:13px}.wv-link{display:inline-flex;gap:10px;align-items:center;margin:24px 0;color:#8e6c27;font-size:13px;font-weight:600}.wv-empty{text-align:center;color:#74816c}.wv .eyebrow{font-size:10px;letter-spacing:2px;color:#a77d27}@media(max-width:800px){.wv-grid{grid-template-columns:1fr}.wv-heading{flex-wrap:wrap;gap:12px}.wv-heading h1{font-size:24px}.wv-heading>button{margin-left:auto}.wv-steps{gap:12px;font-size:11px}.wv-steps span{width:23px;height:23px}.wv-card{padding:20px;border-radius:16px}.wv-icon{width:47px;height:47px}.wv-heading p{font-size:12px}}
@media(max-width:500px){.wv-heading{display:grid;grid-template-columns:47px minmax(0,1fr)}.wv-heading>button{grid-column:2;justify-self:start;margin:4px 0 0}.wv-heading h1{font-size:23px}}
</style>
